UPDATE `locales_item` SET `name_loc8`='Медная монета Иллинга Триаса',`description_loc8`='Быть разбойником очень нелегко. Я надеюсь когда-нибудь заняться своим любимым делом.' WHERE `entry`=43708;
UPDATE `locales_item` SET `name_loc8`='Медная монета Фалстада Громового Молота',`description_loc8`='Я мечтаю дожить до следующей книги.' WHERE `entry`=43709;
UPDATE `locales_item` SET `name_loc8`='Медная монета Генна',`description_loc8`='Ха! Фонтаны в Гилнеасе выполняют в десять раз больше желаний, чем эти!' WHERE `entry`=43710;
UPDATE `locales_item` SET `name_loc8`='Медная монета Иниго',`description_loc8`='Вот если бы вернулся мой отец…' WHERE `entry`=43711;
UPDATE `locales_item` SET `name_loc8`='Медная монета Краса',`description_loc8`='Я молюсь за моих братьев и сестер, что поныне страдают в глубинах Грим Батола. Я непременно освобожу их!' WHERE `entry`=43712;
UPDATE `locales_item` SET `name_loc8`='Медная монета Крилла',`description_loc8`='Бубух. Не бубух? Хочу бубух. Давай, бубух! Эта монета, наверно, испортилась, совсем не взрывается.' WHERE `entry`=43713;
UPDATE `locales_item` SET `name_loc8`='Медная монета Ландро Дальнострела',`description_loc8`='Не хочется бросать эту монетку…' WHERE `entry`=43714;
UPDATE `locales_item` SET `name_loc8`='Медная монета Молока',`description_loc8`='Пусть хоть раз – это все, чего я прошу, хоть раз! – пусть девчонка проедется со мной...' WHERE `entry`=43715;
UPDATE `locales_item` SET `name_loc8`='Медная монета Мурчаля',`description_loc8`='Вот бы вода в Нордсколе была потеплее, а то я от нее в спячку впадаю.' WHERE `entry`=43716;
UPDATE `locales_item` SET `name_loc8`='Медная монета принцессы Калии Менетил',`description_loc8`='Хочу, чтобы этот красавец, лорд Престор, меня заметил! А то он весь погружен в свои мечты…' WHERE `entry`=43717;
UPDATE `locales_item` SET `name_loc8`='Медная монета рядового Маркуса Джонатана',`description_loc8`='Хочу когда-нибудь отрастить роскошные, длинные усы!' WHERE `entry`=43718;
UPDATE `locales_item` SET `name_loc8`='Медная монета Саландрии',`description_loc8`='Когда-нибудь я стану могущественней всех этих магов!' WHERE `entry`=43719;
UPDATE `locales_item` SET `name_loc8`='Медная монета оруженосца Роу',`description_loc8`='Надеюсь, со временем мне удастся добиться, чтобы меня перевели из Штормграда. Снова увидеть Серсею… В этом городе нет ничего хорошего.' WHERE `entry`=43720;
UPDATE `locales_item` SET `name_loc8`='Медная монета Сталвана',`description_loc8`='Вы, маги, отказываетесь снабдить меня тем, что лишь приблизит неизбежный исход, ожидающий двух влюбленных, один из которых столь наивен, что ничего не понимает. Горите все в своих огненных глыбах...' WHERE `entry`=43721;
